caption { font-weight: 700; margin-bottom: 12px; color: #38bdf8; text-align: left; font-size: 1.05rem; }
tfoot td, tfoot th { font-weight: bold; background: #0f172a; color: #f8fafc; }
input, select, textarea {
  width: 100%;
  padding: 10px 14px;
  background: #0f172a;
  border: 1px solid #334155;
  color: #f8fafc;
  border-radius: 6px;
  margin-top: 6px;
  margin-bottom: 14px;
  font-family: inherit;
  font-size: 0.95rem;
}
input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
}
input[type="checkbox"], input[type="radio"] {
  width: auto;
  margin-right: 8px;
  margin-top: 0;
  cursor: pointer;
  accent-color: #22c55e;
}
input[type="color"] {
  height: 48px;
  padding: 4px;
  cursor: pointer;
}
input[type="range"] {
  accent-color: #38bdf8;
}
button {
  background: #22c55e;
  color: #0b0f17;
  font-weight: 700;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.95rem;
  transition: all 0.2s;
}
button:hover {
  background: #16a34a;
  transform: translateY(-1px);
}
.btn-secondary, button[type="reset"] {
  background: #334155;
  color: #f8fafc;
  margin-left: 8px;
}
.btn-secondary:hover, button[type="reset"]:hover {
  background: #475569;
}
.btn-danger {
  background: #ef4444;
  color: #fff;
}
.btn-danger:hover {
  background: #dc2626;
}
fieldset {
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 16px 20px;
  margin-bottom: 16px;
  background: rgba(15, 23, 42, 0.5);
}
legend {
  font-weight: 700;
  color: #38bdf8;
  padding: 0 8px;
}
label {
  font-size: 0.88rem;
  font-weight: 600;
  color: #cbd5e1;
}
details {
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 14px 18px;
  background: #0f172a;
  margin-bottom: 10px;
}
details[open] {
  border-color: #38bdf8;
}
summary {
  font-weight: 600;
  color: #f8fafc;
  cursor: pointer;
}
summary:hover {
  color: #38bdf8;
}
progress, meter {
  width: 100%;
  height: 20px;
  margin-top: 6px;
  margin-bottom: 14px;
  border-radius: 6px;
  overflow: hidden;
}
progress {
  accent-color: #22c55e;
}
audio, video {
  width: 100%;
  border-radius: 8px;
  margin-top: 10px;
}
dialog {
  background: #1e293b;
  color: #f8fafc;
  border: 1px solid #38bdf8;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
}
kbd {
  background: #0f172a;
  border: 1px solid #475569;
  border-bottom: 2px solid #64748b;
  border-radius: 4px;
  padding: 3px 6px;
  font-size: 0.85em;
  font-family: monospace;
  color: #38bdf8;
}
sub, sup {
  font-size: 0.75em;
  color: #38bdf8;
  font-weight: bold;
}
del {
  color: #ef4444;
  text-decoration: line-through;
}
ins {
  color: #22c55e;
  text-decoration: underline;
  font-weight: 600;
}
pre {
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 16px;
  overflow-x: auto;
  font-family: monospace;
}
code {
  font-family: 'Fira Code', monospace;
  color: #38bdf8;
}
.skip-link {
  position: absolute;
  top: -50px;
  left: 10px;
  background: #38bdf8;
  color: #0b0f17;
  padding: 8px 16px;
  font-weight: bold;
  border-radius: 4px;
  z-index: 1000;
  transition: top 0.2s;
}
.skip-link:focus {
  top: 10px;
}
ol.breadcrumb, nav.breadcrumb ol, .breadcrumb-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
ol.breadcrumb li + li::before, nav.breadcrumb ol li + li::before {
  content: '/';
  color: #64748b;
  margin-right: 8px;
}
img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
}
.warning-callout {
  border-left: 4px solid #f59e0b;
  background: rgba(245, 158, 11, 0.1);
  padding: 16px 20px;
  border-radius: 8px;
}

