solution_code.css:
body { margin: 0; padding: 24px; background: #0b0f17; color: #fff; font-family: sans-serif; }
.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1e293b;
  padding: 16px 24px;
  border-radius: 8px;
}
.nav-links { display: flex; gap: 20px; }
.nav-links a { color: #94a3b8; text-decoration: none; font-size: 14px; font-weight: 500; }
.nav-links a:hover { color: #38bdf8; }
.nav-btn { background: #38bdf8; color: #0b0f17; border: none; padding: 8px 16px; border-radius: 6px; font-weight: 600; cursor: pointer; }

