solution_code.css:
body { margin: 0; padding: 24px; background: #0b0f17; color: #fff; font-family: sans-serif; }
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  max-width: 900px;
  margin: 0 auto;
}
.card {
  background: #1e293b;
  padding: 24px;
  border-radius: 8px;
  border: 1px solid #334155;
  min-height: 120px;
}
.card-hero {
  border-color: #38bdf8;
  background: linear-gradient(135deg, #1e293b, #0f172a);
}

