starter_code.css:
body {
  margin: 0;
  padding: 24px;
  background-color: #0b0f17;
  color: #f1f5f9;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
.counter-widget, .timer-widget, .modal-demo, .filter-widget, .star-rating, .interactive-widget {
  max-width: 480px;
  margin: 20px auto;
  background: #1e293b;
  padding: 24px;
  border-radius: 12px;
  border: 1px solid #334155;
  text-align: center;
}
button { cursor: pointer; border-radius: 6px; font-weight: 600; }
.ctrl-btn { width: 44px; height: 44px; font-size: 20px; background: #38bdf8; color: #0b0f17; border: none; margin: 0 12px; }
.reset-btn { display: block; margin: 16px auto 0; background: #334155; color: #fff; border: none; padding: 6px 16px; font-size: 13px; }
#counter-value, #timer-display { font-size: 40px; font-weight: 800; font-family: monospace; display: inline-block; min-width: 60px; color: #38bdf8; }
.time-readout { font-size: 48px; color: #38bdf8; margin-bottom: 16px; }
.btn-green { background: #22c55e; color: #0b0f17; border: none; padding: 10px 18px; margin: 4px; }
.btn-amber { background: #f59e0b; color: #0b0f17; border: none; padding: 10px 18px; margin: 4px; }
.btn-slate { background: #475569; color: #fff; border: none; padding: 10px 18px; margin: 4px; }
.backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 100; }
.dialog-card { background: #1e293b; padding: 24px; border-radius: 8px; border: 1px solid #334155; max-width: 400px; text-align: center; }
.primary-btn { background: #38bdf8; color: #0b0f17; border: none; padding: 10px 20px; font-size: 14px; }
.close-btn { background: #ef4444; color: #fff; border: none; padding: 8px 16px; margin-top: 12px; }
.star { font-size: 32px; color: #475569; cursor: pointer; transition: color 0.2s; }
.star.active { color: #f59e0b; }
.star:hover { color: #fbbf24; }
#search-input, #action-input { width: 100%; padding: 10px; background: #0f172a; border: 1px solid #334155; color: #fff; border-radius: 6px; box-sizing: border-box; margin-bottom: 12px; }
#items-list { list-style: none; padding: 0; margin: 0; text-align: left; }
#items-list li { padding: 10px; border-bottom: 1px solid #334155; }
.result-box { margin-top: 16px; padding: 12px; background: #0f172a; border-radius: 6px; border: 1px dashed #334155; color: #94a3b8; }
.result-box.success { color: #22c55e; border-color: #22c55e; }

