solution_code.javascript:
const stars = document.querySelectorAll('.star');
const output = document.getElementById('rating-output');
let currentRating = 0;

stars.forEach(star => {
  star.addEventListener('click', () => {
    currentRating = Number(star.dataset.rating);
    output.textContent = `Selected: ${currentRating} stars`;
    stars.forEach(s => {
      s.classList.toggle('active', Number(s.dataset.rating) <= currentRating);
    });
  });
});

